	@Test
	void directDeletionUsesServerStartupPolicy() {
		create("protected-direct");
		assertThat(manager.isRepositoryDeletionPasswordRequired()).isTrue();
		assertThatThrownBy(() -> manager.removeRepository("protected-direct"))
				.isInstanceOf(RepositoryDeletionDeniedException.class);
		assertThatThrownBy(() -> manager.removeRepository("protected-direct", PASSWORD.trim()))
				.isInstanceOf(RepositoryDeletionDeniedException.class);
		assertThat(manager.hasRepositoryConfig("protected-direct")).isTrue();
		assertThat(manager.removeRepository("protected-direct", PASSWORD)).isTrue();
	}

