	private static Resource context(String id) {
		HTTPRepository system = new HTTPRepository(TestServer.SERVER_URL + "/repositories/SYSTEM");
		try (RepositoryConnection connection = system.getConnection();
				RepositoryResult<Resource> contexts = connection.getContextIDs()) {
			while (contexts.hasNext()) {
				Resource context = contexts.next();
				if (context.stringValue().endsWith("#" + id)) {
					return context;
				}
			}
			throw new AssertionError("Missing SYSTEM context for " + id);
		} finally {
			system.shutDown();
		}
	}

	private static HttpRequest.Builder credential(HttpRequest.Builder builder, String password) {
		return builder.header(Protocol.REPOSITORY_DELETE_PASSWORD_HEADER,
				Base64.getEncoder().encodeToString(password.getBytes(StandardCharsets.UTF_8)));
	}

	private static HttpResponse<String> send(HttpRequest.Builder builder) throws Exception {
		return HTTP.send(builder.build(), HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
	}
